import{Controller as o}from"@hotwired/stimulus";var s=class extends o{onClick=i=>{let t=i.target;if(t.closest("a, button, input, select, summary"))return;let e=t.closest("[data-href]");if(!e||!this.element.contains(e)||!e.dataset.href)return;let n=window;n.Turbo?n.Turbo.visit(e.dataset.href):location.assign(e.dataset.href)};connect(){this.element.addEventListener("click",this.onClick)}disconnect(){this.element.removeEventListener("click",this.onClick)}};export{s as default};
